#include <iostream>
#include <fstream>
#include <iomanip>
#include <cstdlib>
using namespace std;

int main() {
    ifstream plik("trojkaty.txt");
    int n;
    plik >> n;
    cout << fixed << setprecision(2);
    double suma = 0;
    for (int i = 0; i < n; i++) {
        int x1, y1, x2, y2, x3, y3;
        plik >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;
        double pole = abs(x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2)) / 2.0;
        cout << "Trojkat " << i + 1 << ": pole = " << pole << endl;
        suma += pole;
    }
    cout << "Laczne pole: " << suma << endl;
    return 0;
}
```

